/** How to get the next page. */
export type Pagination = {
  /** The limit that was applied to this page. */
  limit: number;
  /**
   * Pass this as `cursor` to get the next page. `null` means this is the last
   * page.
   */
  next_cursor?: string | null;
};

/** A sentence to turn into the filters of a list. */
export type ParseRequest = {
  /** The list, as `x-autoxide-list` in the API document, e.g. `content.list_content_entries`. */
  resource: string;
  /** What the person typed, 1 to 500 characters, in any language. */
  text: string;
};

/** Filters understood from the sentence. */
export type ParsedFilters = {
  /**
   * What could not be turned into a valid filter: parts of the sentence, or parameters the
   * model proposed that the list does not accept.
   */
  ignored: string[];
  /**
   * Query parameters of the list, each checked against the list's filter schema; send them
   * to the list endpoint as they are.
   */
  params: Record<string, unknown>;
  resource: string;
};

/** The authenticator's answer to a sign-in ceremony. */
export type PasskeyLoginRequest = {
  /** The `ceremony_id` from `POST /api/v1/auth/login/passkey/options`. */
  ceremony_id: string;
  /** The assertion as JSON (`credential.toJSON()` in the browser). */
  credential: Record<string, unknown>;
};

/** A passkey of the signed-in user. Holds no secret. */
export type PasskeyResponse = {
  /**
   * Kind of authenticator, as it identified itself when registered (its AAGUID); `null` when
   * it did not say (or registered before this was kept).
   */
  aaguid?: string | null;
  /**
   * Name of that kind of authenticator, e.g. `Windows Hello`, `Apple Passwords`,
   * `Google Password Manager`; `null` when the kind is not known to the server.
   */
  authenticator?: string | null;
  created_at: string;
  id: string;
  /** When it was last used to sign in; `null` if never. */
  last_used_at?: string | null;
  /** Name the user gave it, e.g. the device. */
  name: string;
};

/** How to pay a billing period. */
export type PayRequest = {
  /** `card`, `wallet`, `vietqr`… — one the operator's payment partner supports; default `card`. */
  method?: string | null;
  /** Page to come back to after paying. */
  return_url?: string | null;
};

/** A payment started for a billing period. */
export type PayResponse = {
  amount: Money;
  /** The partner's page where you pay. */
  checkout_url?: string | null;
  expires_at: string;
  payment_id: string;
  period_id: string;
  /** QR payload, when the partner gives one. */
  qr_payload?: string | null;
  /** `pending` until the partner reports the payment. */
  status: string;
};

/** An email change waiting for its confirmation link. */
export type PendingEmail = {
  email: string;
  /** When the confirmation link stops working. */
  expires_at: string;
};

/** A permission that roles can grant. */
export type PermissionResponse = {
  /** What the permission allows, in the language of `Accept-Language`. */
  description: string;
  /** `<module>.<action>`. */
  name: string;
  /**
   * How careful a grant needs to be: `read`, `write`, `destructive`, `sensitive_data` or
   * `money`.
   */
  risk: string;
  /**
   * `true` when the permission applies to data of an organization unit: a role can grant it
   * for one unit (`unit`), a unit and everything below it (`subtree`), or only the records
   * a person owns (`own`). `false`: it can only be granted for the whole tenant.
   */
  scoped: boolean;
};

/**
 * Everything the server keeps about you: one entry per module that keeps personal
 * data, named after the module.
 */
export type PersonalDataResponse = Record<string, unknown> & {
  /** Your profile, roles, sessions, API keys, passkeys and two-step sign-in status. */
  auth: Record<string, unknown>;
};

/** A shortcut the signed-in user pinned: a screen of the navigation or a record. */
export type Pin = {
  created_at: string;
  id: string;
  /** `navigation` (a screen) or `record`. */
  kind: string;
  /**
   * The screen's label in the language of `Accept-Language`, or the label sent when pinning
   * a record.
   */
  label: string;
  /** Display order, smallest first. */
  position: number;
  /**
   * The screen id from `GET /api/v1/kernel/navigation` (e.g. `content.entries`), or
   * `<record kind>:<id>` for a record (e.g. `content.entry:0190…`).
   */
  target: string;
};

/** What to pin. */
export type PinInput = {
  /** `navigation` or `record`. */
  kind: string;
  /**
   * Required for `record` (1 to 200 characters, e.g. the record's title); ignored for
   * `navigation`, whose label comes from the navigation.
   */
  label?: string | null;
  /**
   * For `navigation`, a screen id from `GET /api/v1/kernel/navigation`; for `record`,
   * `<record kind>:<id>`.
   */
  target: string;
};

/** The new order of all my pins. */
export type PinOrder = {
  /** Ids of every pin of the caller, in the wanted order. */
  ids: string[];
};

/** Where tenants' data is kept: one database. Connection URLs are never shown. */
export type Placement = {
  /** `sqlite` or `postgres`. */
  backend: string;
  /**
   * Country of the servers (ISO 3166-1 alpha-2), for tenants that must keep their data in one
   * country; `null` when unknown. Set with `autoxide placement country`.
   */
  country_code?: string | null;
  created_at: string;
  id: string;
  /** `shared` (many tenants) or `dedicated` (one tenant). */
  kind: string;
  name: string;
  /** `ready`, `behind` (migrations pending: its tenants answer `503`) or `migrating`. */
  schema_state: string;
  storage?: PlacementStorage | null;
};

/** Migrations of one placement. */
export type PlacementMigrationList = {
  /** `<module>/<migration>`: pending ones for a dry run, applied ones for a run. */
  migrations: string[];
  placement: string;
};

/** Where a placement keeps its tenants' files. Access keys are never shown. */
export type PlacementStorage = {
  /** Bucket (`s3`). */
  bucket?: string | null;
  /** Whether an access key is stored (`s3`); its value is never shown. */
  credentials: boolean;
  /** Directory on the server (`local`). */
  dir?: string | null;
  /** Address of the S3-compatible service (`s3`); `null` for Amazon S3. */
  endpoint?: string | null;
  /**
   * `local` (a directory on the server), `s3` (an S3 or S3-compatible bucket), or
   * `unreadable` (the stored settings cannot be decrypted with the configured secret key).
   */
  kind: string;
  /** Folder inside the bucket (`s3`). */
  prefix?: string | null;
  /** Region of the bucket (`s3`). */
  region?: string | null;
};

/** A plan to create, or the whole new content of a plan. */
export type PlanRequest = {
  /** Unique code, `[a-z][a-z0-9_-]{0,63}`. */
  code: string;
  /** Up to 5000 characters. */
  description?: string;
  /** Features to turn on, by key (`features` of the modules). */
  features?: string[];
  /** 0 to 3650; default 7. */
  grace_days?: number;
  /** Make this the default plan (an active base plan); the previous default stops being one. */
  is_default?: boolean;
  /** `base` (default) or `addon`. */
  kind?: string;
  /**
   * Limits by key (`limits` of the modules); `null` is unlimited, a limit left out is 0. A limit
   * that has parts also takes a cap per part, `<limit>.<part>` (for example
   * `organizations.units.store`); a part left out has no cap of its own.
   */
  limits?: {
    [key: string]: number | null;
  };
  /**
   * Modules to turn on, by name (`GET /api/v1/kernel/modules`). A base plan must also turn on
   * the modules they need (`requires`).
   */
  modules?: string[];
  /** Name shown to customers, 1 to 200 characters. */
  name: string;
  /** `shared` (default) or `dedicated`. */
  placement?: string;
  /** 0 to 3650; default 7. */
  renewal_lead_days?: number;
  /** A new tenant must pass identity checks first (only through `POST /signups`). */
  requires_kyc?: boolean;
  /** 0 to 3650; default 90. */
  retention_days?: number;
  sample_data?: boolean;
  /**
   * New tenants may choose this plan when they sign up by themselves (an active base plan;
   * sign-up must be turned on with `AUTOXIDE_PLANS_SIGNUP`). Default `false`.
   */
  self_signup?: boolean;
  /** `draft` (default) or `active`. Retire a plan with `POST /plans/{id}/retire`. */
  status?: string;
  /** 0 to 3650; default 30. */
  suspend_days?: number;
  /** 0 to 3650; default 0. */
  trial_days?: number;
};

/** A plan: the modules, features and limits a tenant gets, and its prices. */
export type PlanResponse = {
  code: string;
  created_at: string;
  description: string;
  /** Features turned on. */
  features: string[];
  /** Days a tenant keeps full access after a period ends unpaid. */
  grace_days: number;
  id: string;
  /**
   * Tenants without a subscription get this plan. At most one plan is the default; with none,
   * such tenants are not limited.
   */
  is_default: boolean;
  /** `base` (a tenant has one) or `addon` (added on top, with a quantity). */
  kind: string;
  /** Limits by key; `null` means unlimited. A limit not listed is 0. */
  limits: {
    [key: string]: number | null;
  };
  /** Modules turned on (modules that are always on are not listed). */
  modules: string[];
  name: string;
  /** Where a new tenant on this plan keeps its data: `shared` or `dedicated`. */
  placement: string;
  prices: PriceResponse[];
  /** Days before a period ends that the next one is billed and a reminder sent. */
  renewal_lead_days: number;
  /** A new tenant on this plan must pass identity checks first. */
  requires_kyc: boolean;
  /** Days the data of a canceled subscription is kept before the tenant is deleted. */
  retention_days: number;
  /** A new tenant on this plan starts with sample data. */
  sample_data: boolean;
  /** New tenants may choose this plan when they sign up by themselves (`POST /signups`). */
  self_signup: boolean;
  /** `draft`, `active` (sold) or `retired` (no longer sold; tenants on it keep it). */
  status: string;
  /**
   * Tenants on the plan now (subscriptions not canceled, as base plan or add-on). Only for
   * platform staff: `null` in the public catalog.
   */
  subscriber_count?: number | null;
  /** Days a suspended (read-only) subscription waits before it is canceled. */
  suspend_days: number;
  /** Days of free trial for a tenant that never had one; 0 for none. */
  trial_days: number;
  updated_at: string;
};

/** The subscription of a tenant. */
export type PlanSubscription = {
  addons: AddonItem[];
  /** Cancels when the current period ends. */
  cancel_at_period_end: boolean;
  canceled_at?: string | null;
  created_at: string;
  current_period_end: string;
  current_period_start: string;
  delete_after?: string | null;
  grace_ends_at?: string | null;
  id: string;
  /** Code of the plan (also when it is no longer sold). */
  plan_code?: string | null;
  plan_id: string;
  /** Name of the plan (also when it is no longer sold). */
  plan_name?: string | null;
  price_id?: string | null;
  /** Plan the subscription moves to when the period ends (after a downgrade). */
  scheduled_plan_id?: string | null;
  scheduled_price_id?: string | null;
  /**
   * `trialing`, `active`, `past_due` (unpaid, in the grace period), `suspended` (read-only),
   * `canceled` (read-only, data kept until `delete_after`) or `deleted`.
   */
  status: string;
  suspended_at?: string | null;
  tenant_id: string;
  trial_ends_at?: string | null;
  /** The tenant already had its free trial. */
  trial_used: boolean;
  updated_at: string;
};

