/** A new price of a plan. */
export type PriceRequest = {
  /** Amount per period (`recurring`) or per unit above `included` (`metered`); not negative. */
  amount: Money;
  /** With `metered`: use included each period; default 0. */
  included?: number;
  /** `month` or `year`. */
  interval: string;
  /** 1 to 12; default 1. */
  interval_count?: number;
  /** `recurring` or `metered`. */
  kind: string;
  /** With `metered`: the metered limit charged for, e.g. `kernel.api_requests`. */
  limit_key?: string | null;
  /** Tax category, when known. */
  tax_category?: string | null;
};

/**
 * A price of a plan. Prices never change: a new price is a new row, the old one is deactivated;
 * subscriptions keep their price until they change plan.
 */
export type PriceResponse = {
  /** `false`: no longer sold at this price. */
  active: boolean;
  /** Amount per period (`recurring`) or per unit above `included` (`metered`). */
  amount: Money;
  created_at: string;
  id: string;
  /** Use included each period before a metered price applies. */
  included: number;
  /** `month` or `year`. */
  interval: string;
  /** How many `interval`s a period lasts, 1 to 12. */
  interval_count: number;
  /** `recurring` (charged each period) or `metered` (charged for use of `limit_key`). */
  kind: string;
  /** The metered limit this price charges for. */
  limit_key?: string | null;
  /** Tax category of the price, when set. */
  tax_category?: string | null;
};

/** An error, as RFC 9457 Problem Details. Branch on `code`; show `detail` to people. */
export type Problem = {
  /**
   * Stable machine-readable identifier of the problem. Branch on this, never
   * on `detail`.
   */
  code: string;
  /** Human-readable explanation of what went wrong and how to fix it. */
  detail: string;
  /** One entry per invalid input field. Present only for validation problems. */
  errors?: ProblemField[];
  /**
   * Finer, stable reason for some codes, documented with the code — e.g. for a refused link
   * token: `expired`, `used` or `unknown`.
   */
  reason?: string | null;
  /** The HTTP status code, repeated in the body. */
  status: number;
  /** The standard phrase for the HTTP status, e.g. `Not Found`. */
  title: string;
  /** Always `about:blank`: the problem is identified by `code`, not by a URI. */
  type: string;
};

/** One invalid field of the request. */
export type ProblemField = {
  /** Stable identifier of the kind of problem: `required`, `length`, `range`… */
  code: string;
  /** What the value must look like. */
  detail: string;
  /** Path to the field: `name`, `address.city`, `items[2].quantity`. */
  field: string;
};

/** A display name. */
export type ProfileRequest = {
  /**
   * 1 to 50 characters; reserved names (`AUTOXIDE_COMMENTS_RESERVED_NAMES`) are for
   * moderators; no two users share a name.
   */
  display_name: string;
};

/** Create a tenant on a plan. */
export type ProvisioningRequest = {
  /** Who administers the new tenant: invited by email with the role `admin`. */
  admin_email: string;
  /** Their name, up to 200 characters. */
  admin_name?: string | null;
  /** Name of the new tenant, 1 to 200 characters. */
  name: string;
  /** Parent tenant, for chains. */
  parent_id?: string | null;
  /**
   * Name of the placement for its data, of the plan's kind; default `main` for a `shared` plan.
   * Required for a `dedicated` plan.
   */
  placement?: string | null;
  /** An active base plan. */
  plan_id: string;
  /** An active recurring price of that plan. */
  price_id?: string | null;
  /** Add the sample data of the modules the plan turns on; default: the plan's `sample_data`. */
  sample_data?: boolean | null;
  /** Short name of the new tenant: 1 to 63 lower-case letters, digits and `-`. */
  slug: string;
  /** Start with the plan's free trial; default `true`. */
  trial?: boolean;
};

/** A request to create a tenant on a plan, and how far it went. */
export type ProvisioningResponse = {
  admin_email: string;
  admin_name?: string | null;
  created_at: string;
  error?: string | null;
  /** Code of the error that stopped it, when `failed`. */
  error_code?: string | null;
  id: string;
  parent_tenant_id?: string | null;
  /** Name of the placement; `null`: `main`. */
  placement?: string | null;
  plan_id: string;
  price_id?: string | null;
  requested_by?: string | null;
  sample_data: boolean;
  slug: string;
  /** `pending`, `running`, `failed` (see `error`; fix it, then `POST …/retry`) or `done`. */
  status: string;
  /** The last step done: `created`, `tenant_created`, `subscribed`, `seeded`, `invited`, `done`. */
  step: string;
  /** Every step done, oldest first. */
  steps: ProvisioningStep[];
  /** The new tenant, once created. */
  tenant_id?: string | null;
  tenant_name: string;
  trial: boolean;
  updated_at: string;
};

/** One step a provisioning went through. */
export type ProvisioningStep = {
  at: string;
  /** `created`, `tenant_created`, `subscribed`, `seeded`, `invited` or `done`. */
  step: string;
};

/** An author of an entry. */
export type PublicAuthor = {
  avatar_media_id?: string | null;
  display_name: string;
  id: string;
  slug: string;
};

/** An author as readers see them. */
export type PublicAuthorPage = {
  avatar?: PublicMedia | null;
  bio: string;
  display_name: string;
  id: string;
  slug: string;
  website_url: string;
};

/** A comment, as shown to everyone. */
export type PublicComment = {
  author: CommentAuthor;
  /**
   * Stable codes of what the author was on the target when writing, e.g. `seller` (manages
   * the product) or `verified_buyer` (received it); empty for most comments. Show your own
   * label for each code.
   */
  badges: string[];
  /** The text as written (plain text or Markdown, see `format`). Never insert it as HTML. */
  body: string;
  /**
   * The text as safe HTML: everything escaped, line breaks as `<br>`, `http(s)` addresses as
   * links with `rel="nofollow ugc noopener"`. For `markdown`, only `<p>`, `<strong>`, `<em>`,
   * `<a>`, `<blockquote>`, `<code>` and `<pre>` besides: raw HTML shows as text, images as
   * their text. Insert this, never `body`.
   */
  body_html: string;
  created_at: string;
  /** Deleted by its author: no text or name, kept so its replies stay in place. */
  deleted: boolean;
  /** When the author last changed it. */
  edited_at?: string | null;
  /** How `body` is written: `text` or `markdown`. */
  format: Format;
  id: string;
  /** The top-level comment, for a reply; `null` for a top-level comment. */
  parent_id?: string | null;
  /** Shown replies (top-level comments only). */
  reply_count: number;
  /** The comment this one answers (the top-level comment or another reply in the thread). */
  reply_to_id?: string | null;
  /** The comment that starts the thread (itself for a top-level comment). */
  root_id: string;
  target_id: string;
  target_type: string;
};

/** A record of another module embedded in an entry. */
export type PublicEmbed = {
  id: string;
  /** Representative image: the id of a public media item (its file: `GET /api/v1/media/{id}/content`). */
  image?: string | null;
  kind: string;
  summary: string;
  title: string;
  /** Public path of the record, without domain. */
  url?: string | null;
};

/** A published post or page, as readers see it. */
export type PublicEntryResponse = {
  /**
   * A person wrote or edited the content from AI suggestions: label it as AI-assisted (Vietnam's
   * Law on Artificial Intelligence 134/2025/QH15, from 2026-03-01).
   */
  ai_assisted: boolean;
  /**
   * The content was generated by AI. Show readers a notice when your rules (for example
   * Article 50 of the EU AI Act) ask for one.
   */
  ai_generated: boolean;
  /**
   * A person reviewed the AI-generated content and took editorial responsibility when it
   * was published. Always `false` when `ai_generated` is `false`.
   */
  ai_reviewed: boolean;
  /** Authors; the first is the main one. */
  authors: PublicAuthor[];
  body: BodyNode;
  /**
   * The images used in `body` (nodes of type `image`), in order of appearance: find one by
   * the `mediaId` of the node to get its size and smaller copies for `srcset`. An image
   * that is no longer public is left out. `alt` here is the one of the media library; the
   * node carries its own.
   */
  body_media: PublicMedia[];
  body_schema_version: number;
  /** Last change of the published content (sitemap `lastmod`, feed `updated`). */
  content_modified_at: string;
  /**
   * The tenant's custom fields shown to readers (those of visibility `public`), by key, as they
   * were when the entry was published.
   */
  custom_fields: Record<string, unknown>;
  /**
   * Records of other modules embedded in `body` (nodes `embed` with `kind` and `id`, e.g. a
   * product), keyed by `<kind>:<id>`, in the entry's language. A record that is not public
   * (any more) is left out: skip its node. Prices and stock are not here — read them from the
   * owning module's public API, so they are always current.
   */
  embeds: {
    [key: string]: PublicEmbed;
  };
  excerpt: string;
  featured_media?: PublicMedia | null;
  first_published_at: string;
  /** Stable id (also the id of feed items). */
  id: string;
  kind: Kind;
  locale: string;
  parent_id?: string | null;
  /** Address computed by the server, without domain or language prefix. */
  path: string;
  /** The date shown as the publication date. */
  published_at: string;
  reading_time_minutes: number;
  seo: PublicSeo;
  slug: string;
  /** Categories and tags; the first category is the main one. */
  terms: PublicTerm[];
  title: string;
  translation_group_id: string;
  /** Other published languages of this entry, for `hreflang`. */
  translations: PublicTranslation[];
  word_count: number;
};

/** A field, in the asked language. */
export type PublicField = {
  help?: string | null;
  /** Send the answer under this key in `data`. */
  key: string;
  /**
   * For `consent`: the exact text to show next to the box (it is stored with the
   * submission as proof).
   */
  label: string;
  max?: number | null;
  max_length?: number | null;
  min?: number | null;
  min_length?: number | null;
  /** Choices of `select`, `radio` and `checkbox`. */
  options?: PublicOption[];
  placeholder?: string | null;
  required: boolean;
  type: FieldType;
};

/** A form, as a website shows it. */
export type PublicFormResponse = {
  fields: PublicField[];
  key: string;
  /** Language of the texts below. */
  locale: Locale;
  name: string;
  /** `closed`: show that the form is closed; sending is refused with `forms.closed`. */
  status: FormStatus;
  /** Shown after sending (also returned by the submit endpoint). */
  success_message: string;
  /**
   * Ask `GET /api/v1/antispam/token?scope=<token_scope>` for a form token each time the
   * form is shown, and send it as `form_token`.
   */
  token_scope: string;
  /** Version of the fields. */
  version: number;
};

/** A list open to public sign-up, in one language. */
export type PublicList = {
  description: string;
  /** Subscribing needs a click on a link sent by mail. */
  double_opt_in: boolean;
  /** Send it in `lists` to subscribe. */
  key: string;
  name: string;
};

/** The lists a website may offer. */
export type PublicListsResponse = {
  lists: PublicList[];
  /** Language of the texts. */
  locale: NewsletterLocale;
  /**
   * Ask `GET /api/v1/antispam/token?scope=<token_scope>` for a form token each time the
   * sign-up form is shown, and send it as `form_token`.
   */
  token_scope: string;
};

/** An image, as readers load it. */
export type PublicMedia = {
  /** Text alternative. */
  alt: string;
  /**
   * `alt` is the media library's and was written from an AI suggestion: label it (Vietnam's
   * Law on Artificial Intelligence 134/2025/QH15). An `alt` set on the entry follows the
   * entry's `ai_assisted`.
   */
  alt_ai_assisted: boolean;
  height?: number | null;
  /** Media item id. */
  id: string;
  /** Where to load it (versioned: cache it for long). */
  url: string;
  /** Smaller copies, narrowest first, for `srcset`. */
  variants: PublicVariant[];
  width?: number | null;
};

/** A navigation menu as readers see it. */
export type PublicMenu = {
  items: PublicMenuItem[];
  key: string;
  /** The language actually returned (the default language when the menu is not translated). */
  locale: string;
};

/** A small label on a menu item. */
export type PublicMenuBadge = {
  text: string;
  /** `sale`, `brand`, `new` or `neutral`. */
  tone: string;
};

/** An object featured in a drop-down panel. */
export type PublicMenuFeature = {
  href?: string | null;
  image?: PublicMenuImage | null;
  ref: PublicMenuTarget;
  summary: string;
  title: string;
};

/** A public picture. */
export type PublicMenuImage = {
  alt: string;
  height?: number | null;
  /** Address of the picture; it changes when the picture changes, so it may be cached long. */
  url: string;
  width?: number | null;
};

/** An item of a public menu. */
export type PublicMenuItem = {
  children: PublicMenuItem[];
  entry_id?: string | null;
  /**
   * The address: a path in the site (for an entry), or the address given. Empty for a
   * term: build its address from `term`.
   */
  href: string;
  label: string;
  term?: PublicTerm | null;
};

/** An object of a module, as a resource type and an id. */
export type PublicMenuTarget = {
  id: string;
  kind: string;
};

/** A choice, in the asked language. */
export type PublicOption = {
  /** What to show. */
  label: string;
  /** What to send. */
  value: string;
};

/** Changes to a public profile. Omitted fields stay as they are; `null` clears. */
export type PublicProfileRequest = {
  address?: AddressInput | null;
  cover_media_id?: string | null;
  /** 1 to 200 characters; `null` goes back to the unit's name. */
  display_name?: string | null;
  /** Replaces every range. */
  opening_hours?: {
    /** Local time `HH:MM`, after `opens`. */
    closes: string;
    /** ISO day of the week: 1 Monday … 7 Sunday. */
    day: number;
    /** Local time `HH:MM` (the unit's time zone, setting `organizations.timezone`). */
    opens: string;
  }[] | null;
  pickup?: boolean | null;
  position?: number | null;
  public?: boolean | null;
  /** Replaces every special day. */
  special_days?: {
    /** Closed all day. */
    closed?: boolean;
    closes?: string | null;
    /** `YYYY-MM-DD`. */
    date: string;
    /** Shown to visitors, up to 200 characters. */
    note?: string | null;
    /** When open: local time `HH:MM`. */
    opens?: string | null;
  }[] | null;
};

/** The public profile of an organization unit, as websites show it. */
export type PublicProfileResponse = {
  address?: Address | null;
  /** Cover image (id in the `media` library). */
  cover_media_id?: string | null;
  /** Name shown to visitors; defaults to the unit's name. */
  display_name: string;
  opening_hours: {
    /** Local time `HH:MM`, after `opens`. */
    closes: string;
    /** ISO day of the week: 1 Monday … 7 Sunday. */
    day: number;
    /** Local time `HH:MM` (the unit's time zone, setting `organizations.timezone`). */
    opens: string;
  }[];
  /** Customers can pick up orders here. */
  pickup: boolean;
  /** Order among the public units (smaller first). */
  position: number;
  /** Shown on websites (`GET /api/v1/organizations/public/stores`). */
  public: boolean;
  special_days: {
    /** Closed all day. */
    closed?: boolean;
    closes?: string | null;
    /** `YYYY-MM-DD`. */
    date: string;
    /** Shown to visitors, up to 200 characters. */
    note?: string | null;
    /** When open: local time `HH:MM`. */
    opens?: string | null;
  }[];
  unit_id: string;
  unit_type: string;
  /** `null` until the profile is first saved. */
  updated_at?: string | null;
};

/** Search engine and sharing data. */
